import{_ as t,o as e,c as a,a5 as r}from"./chunks/framework.CnBNXlt7.js";const m=JSON.parse('{"title":"2025/06/16","description":"","frontmatter":{},"headers":[],"relativePath":"trip/journey/20250616.md","filePath":"trip/journey/20250616.md","lastUpdated":1752144819000}'),o={name:"trip/journey/20250616.md"};function _(n,p,i,s,d,c){return e(),a("div",null,[...p[0]||(p[0]=[r('<h1 id="_2025-06-16" tabindex="-1">2025/06/16 <a class="header-anchor" href="#_2025-06-16" aria-label="Permalink to &quot;2025/06/16&quot;">​</a></h1><p>飞行日记 2025/6/16 周一</p><p>天气预报下雨，实际天气，晴转多云，体感温度30度，树荫下偶尔有风</p><p>早上9点半，提前约好了机场顺风车，简单收拾收拾，想着10:20出发下楼，就来得及。玩玩手机，10:10左右司机取消了订单，唉。迅速重新下单，等了10多分钟没人接单。</p><p>20分左右，决定下楼吧，看看坐公交车怎么样。刚到楼下，有司机接单了，运气还可以。走到门口，一辆公交车急速闪过。打电话问司机，说没接到其他人，不出车。公交应该也可以，但是刚走了一辆。走到公交站，预计下一辆10:50-11:00了，到机场估计赶不上飞机。继续等等顺风车，没有动静。</p><p>决定打车去，开始叫车，50块加到70块，都没人接单。热浪冲击，伴随饥饿口渴，浑身湿透，有点烦躁。想着让小挂件送送吧，没有路子了。顺带让小挂件叫车，好在叫到了一辆顺风车。而我也叫到了一口价，80块有人来接。最终看到了顺风车到来，取消了打车。</p><p>坐上车，先去三号点接第三位乘客，一分钟没多等就接到了。而后又去四号点，接第四位乘客。司机说到11:40不来就不等了，其实已经等了15分钟，好在来了。放好行李，直接出发。</p><p>可恰好司机ETC故障，读不上，耽误了一分钟。进入高速，就140时速，司机也是好身手，这网约车（东风风神E70）还能开这么快。</p><p>大概20多分钟开到，11:43-12:03差不多，挺离谱的。高速140，下高速120，也是真牛。</p><p>走到贵宾楼大概10分钟左右，整两盘自助，饱餐一顿。被通知航路拥堵延误了。</p><p>接下来的行程要变动了，但是手机可以充上电了。都有好的一面。</p><p>好在，没有很久，13:30登机，40上飞机坐下。估计航路天气不行，一直没有推出，提前发了面包，饮水。</p><p>14:25左右推出，30离地起飞，说是飞行时间1h35m，希望吧。</p><p>空中看到速度似乎到达1050km/h左右，有点牛。为什么汽车100到130，感觉很明显，高铁也是200到350能很明显感觉到高速。飞机在800到1100，怎么感觉不到速度快慢。飞机时速上限多少？如果能一直1500时速多好，压缩飞行时长。起飞速度300不到…</p><p>浙江这边雨下的真的挺大，不是说现在。大河小河全都是一片黄色，很多绿树都泡在河里，很明显…</p><p>13抵达，滑行（taxiing）很久，</p>',16)])])}const u=t(o,[["render",_]]);export{m as __pageData,u as default};
